CUR = {"pal": ["rosewood", "eucalyptus", "greentea", "golddust"]}

def _nbsp(v):
    """Vaste spatie voor eenheden: 2 m, 5 kg, 16 mm, 9 inch, 9 cali, 2,5 m."""
    import re
    return re.sub(r"(\d)[ ](m|kg|mm|inch|cali|coliai|colių|ίντσες|cm)\b", lambda m: m.group(1) + NB + m.group(2), v)

def fill_pal(b, c):
    pr = pair(b["pal"])
    lab = {f"p{i}": G["pal_label"](k, short=False).replace("Fashion ", "").replace("Pastel ", "") for i, k in enumerate(pr + [k for k in b["pal"][:4] if k not in pr])}
    def f(v):
        if not isinstance(v, str): return v
        if "{p" in v: v = v.format(**lab)
        return _nbsp(v)
    out = {}
    for k, v in c.items():
        if isinstance(v, str): out[k] = f(v)
        elif isinstance(v, list): out[k] = [[f(x) for x in item] if isinstance(item, list) else f(item) for item in v]
        else: out[k] = v
    qs = VARIANTS[b["lang"]]["client_question"]
    qi = qs.index(c["client_question"]) if c["client_question"] in qs else 0
    out["client_answer"] = f(c["client_answers"][qi])
    return out

def _bl(key, size, cls="", extra=""):
    return G["balloon"](key, "fashion", size, extra_style=extra, cls=cls)

def _lum(key):
    h = G["SX"][key]["hex"].lstrip("#"); r, g, b = (int(h[i:i+2], 16) for i in (0, 2, 4))
    return .299 * r + .587 * g + .114 * b

def pair(keys):
    """De 2 paletkleuren met het grootste helderheidsverschil: één lichte, één diepe toon (leesbare spiraal)."""
    ks = list(keys[:4]); ks.sort(key=_lum)
    return [ks[-1], ks[0]]

def facts_grid(items, cls="facts", num_size=44, lab_size=20):
    esc = G["esc"]
    def fs(n):
        L = len(n); return num_size if L <= 6 else (int(num_size * .72) if L <= 11 else int(num_size * .55))
    cells = "".join(f'<div class="fact"><b style="font-size:{fs(n)}px">{esc(n)}</b><span style="font-size:{lab_size}px">{esc(l)}</span></div>' for n, l in items)
    return f'<div class="{cls}">{cells}</div>'

def quad(keys, size=100, ink="#111"):
    """Een quad: 4 ballonnen rond één knooppunt, kleur A en B afwisselend."""
    ratio = G["PHOTO_RATIO"]; h = int(size * ratio); w = int(h * 2.05); ch = w
    cx = w // 2; cy = ch // 2
    cols = [keys[0], keys[1 % len(keys)], keys[0], keys[1 % len(keys)]]
    out = f'<div style="position:relative;width:{w}px;height:{ch}px">'
    for k, a in zip(cols, (-45, 45, 135, 225)):
        out += f'<div style="position:absolute;left:{cx - size//2}px;top:{cy - h}px;transform-origin:50% 100%;transform:rotate({a}deg)">{_bl(k, size)}</div>'
    out += f'<div style="position:absolute;left:{cx-8}px;top:{cy-8}px;width:16px;height:16px;border-radius:50%;background:{ink}"></div>'
    return out + '</div>'

def spiral_arch(keys, w=330, h=300, n=13, size=40, twist=28, loose=False):
    """Spiraalboog: quads langs een halve ellips; elke quad draait 'twist' graden verder zodat de kleurlijnen spiraliseren.
    loose=True: willekeurige kleuren, maten en gaten (de 'oude' manier)."""
    import math, random
    rnd = random.Random(7)
    out = f'<div style="position:relative;width:{w}px;height:{h}px">'
    cx, cy, rx, ry = w / 2, h - 50, w / 2 - 50, h - 112
    for i in range(n):
        t = math.pi * (1 - i / (n - 1))
        x, y = cx + rx * math.cos(t), cy - ry * math.sin(t)
        ang = -math.degrees(t) + 90
        if loose:
            x += rnd.randint(-10, 10); y += rnd.randint(-8, 8)
            s = size + rnd.randint(-10, 12); rot = ang + rnd.randint(-40, 40)
            cols = [rnd.choice(keys) for _ in range(4)]
            if i % 4 == 2: continue
        else:
            s = size; rot = ang + i * twist
            cols = [keys[0], keys[1 % len(keys)], keys[0], keys[1 % len(keys)]]
        bh = int(s * G["PHOTO_RATIO"])
        qw = int(bh * 1.6)
        out += f'<div style="position:absolute;left:{int(x - qw/2)}px;top:{int(y - qw/2)}px;width:{qw}px;height:{qw}px;transform:rotate({rot:.0f}deg)">'
        for k, a in zip(cols, (-45, 45, 135, 225)):
            out += f'<div style="position:absolute;left:{qw//2 - s//2}px;top:{qw//2 - bh}px;transform-origin:50% 100%;transform:rotate({a}deg)">{_bl(k, s)}</div>'
        out += '</div>'
    return out + '</div>'

def chips_row(items, ink="#111", bg="#fff", small=False):
    esc = G["esc"]; extra = "font-size:15px;padding:4px 10px;" if small else ""
    return '<div style="display:flex;justify-content:center;gap:6px;flex-wrap:wrap">' + "".join(f'<span class="tchip" style="{extra}border-color:{ink};color:{ink};background:{bg}">{esc(t)}</span>' for t in items) + '</div>'

def loose_visual(keys, c, ink="#111"):
    """'Losse stapel': rommelige boog met gaten en een rode 'los'-stempel."""
    esc = G["esc"]
    return (f'<div style="position:relative;width:330px;height:380px">'
            f'<div style="position:absolute;left:0;top:0">{spiral_arch(keys, 330, 300, 13, 40, 28, loose=True)}</div>'
            f'<div style="position:absolute;left:40px;top:290px;transform:rotate(-6deg);background:#fff;color:#E03131;border:3px solid {ink};'
            f'border-radius:10px;padding:8px 16px;font-size:22px;font-weight:900;letter-spacing:.06em;text-transform:uppercase;box-shadow:0 4px 0 rgba(0,0,0,.18);white-space:nowrap">{esc(c["loose_lbl"])} ✕</div></div>')

def tight_visual(keys, c, ink="#111"):
    """'Strakke spiraal': nette spiraalboog + chips + stempel '36 quads'."""
    esc = G["esc"]
    return (f'<div style="position:relative;width:330px;height:380px">'
            f'<div style="position:absolute;left:0;top:0">{spiral_arch(keys, 330, 300, 13, 40, 28)}</div>'
            f'<div style="position:absolute;left:-30px;right:-30px;top:292px">{chips_row(c["chips"], ink, "#fff", True)}</div>'
            f'<div style="position:absolute;left:90px;top:332px;transform:rotate(-4deg);background:#fff;color:{ink};border:3px solid {ink};border-radius:10px;padding:8px 16px;font-size:22px;font-weight:900;letter-spacing:.06em;text-transform:uppercase;box-shadow:0 4px 0 rgba(0,0,0,.18);white-space:nowrap">✓ {esc(c["quads_lbl"])}</div></div>')

def two_pairs(keys, c, ink="#111", body_size=21, lbl_size=24, gap=26, vh=250, sc=1.0):
    """Voorbeeldslide: links de tutorial-boog (violet + lila benaderd met violet en whitesand), rechts de boog in het distri-palet."""
    esc = G["esc"]
    tut = ["violet", "whitesand"]
    vis = [f'<div style="height:{vh}px;display:flex;align-items:flex-end;justify-content:center;width:100%"><div style="transform:scale({sc:.2f});transform-origin:bottom center">{spiral_arch(tut, 330, 300, 13, 40, 28)}</div></div>',
           f'<div style="height:{vh}px;display:flex;align-items:flex-end;justify-content:center;width:100%"><div style="transform:scale({sc:.2f});transform-origin:bottom center">{spiral_arch(keys, 330, 300, 13, 40, 28)}</div></div>']
    cols = ""
    for v, (t, body) in zip(vis, c["ex_items"]):
        cols += (f'<div style="flex:1;min-width:0;display:flex;flex-direction:column;align-items:center;gap:10px">{v}'
                 f'<div style="font-size:{body_size}px;line-height:1.3;text-align:center"><b style="font-size:{lbl_size}px;display:block;margin-bottom:4px">{esc(t)}</b>{esc(body)}</div></div>')
    return f'<div style="display:flex;gap:{gap}px;align-items:flex-start;width:100%">{cols}</div>'

def rule_cards(c, cls="alts", title_size=24, body_size=18, font=None):
    esc = G["esc"]
    out = f'<div class="{cls}"' + (f' style="font-family:\'{font}\'"' if font else '') + '>'
    n = len(c["alts"])
    for i, (t, body) in enumerate(c["alts"]):
        span = ' style="grid-column:1/-1"' if (i == n - 1 and n % 2 == 1) else ''
        out += f'<div class="alt"{span}><b style="font-size:{title_size}px"><span class="num">{i+1}</span>{esc(t)}</b><span style="font-size:{body_size}px">{esc(body)}</span></div>'
    return out + '</div>'

def avoid_list(c, cls=""):
    esc = G["esc"]
    return ('<div class="' + cls + '">' + "".join(f'<div class="step"><b>{i+1}.</b><span>{esc(s)}</span></div>' for i, s in enumerate(c["steps5"])) + '</div>')

